10	
11	const ENVIRONMENTS: readonly Environment[] = ['local', 'ci', 'staging', 'production'];
12	
13	export interface DesktopConfig {
14	  environment: Environment;
15	  /** The API origin the identity exchange is spoken to. */
16	  apiBaseUrl: string;
17	  web3AuthClientId: string;
18	  verifier: string;
19	  /** Absent means this build collects no Google credential, so offers none. */
20	  googleClientId: string | undefined;
21	}
