23	/**
24	 * Absent, empty and whitespace-only are one state: a repo variable set to a
25	 * stray space is unset, not configured.
26	 */
27	function configured(value: string | undefined): string | undefined {
28	  return value?.trim() || undefined;
29	}
30	
31	/**
32	 * A typo is rejected rather than defaulted: it would silently pick the wrong
33	 * Web3Auth network, and so a different identity over an empty vault.
34	 */
35	function environmentOf(env: Partial<ImportMetaEnv>): Environment {
36	  const value = configured(env.VITE_ENVIRONMENT);
37	  if (value === undefined) return 'local';
38	  if (!ENVIRONMENTS.includes(value as Environment)) {
39	    throw new Error(`VITE_ENVIRONMENT must be one of ${ENVIRONMENTS.join(', ')}`);
40	  }
41	  return value as Environment;
42	}
