44	export function desktopConfig(env: Partial<ImportMetaEnv>): DesktopConfig {
45	  const web3AuthClientId = configured(env.VITE_WEB3AUTH_CLIENT_ID);
46	  const verifier = configured(env.VITE_WEB3AUTH_VERIFIER);
