51	  }
52	  return {
53	    environment: environmentOf(env),
54	    apiBaseUrl: configured(env.VITE_API_URL) ?? DEFAULT_API_URL,
55	    web3AuthClientId,
56	    verifier,
57	    googleClientId: configured(env.VITE_GOOGLE_CLIENT_ID),
