9	import type { IdentityMethod } from '@cipherbox/login';
10	
11	export interface ShellModel {
12	  phase: 'starting' | 'signedOut' | 'signedIn';
13	  /** True while a restore, login, or logout is in flight. */
14	  busy: boolean;
15	  /** The methods the login flow offers, in the order to show them. */
16	  methods: readonly IdentityMethod[];
17	  /** The signed-in address, when the method carried one. */
18	  email: string | null;
19	  error: string | null;
20	  /** True once CipherBox has sent a code to the address in the form. */
21	  codeSent: boolean;
22	  /** The address the form holds, kept across a re-render. */
23	  address: string;
24	}
25	
26	export interface ShellActions {
27	  google(): void;
28	  sendEmailCode(email: string): void;
29	  submitEmailCode(email: string, code: string): void;
30	  logout(): void;
31	}
32	
33	type Renderer = (model: ShellModel, actions: ShellActions) => HTMLElement;
34	
35	/** One renderer per method the shell can collect. */
36	const RENDERERS: Partial<Record<IdentityMethod, Renderer>> = {
37	  google: googleButton,
38	  email: emailForm,
39	};
40	
41	export function renderShell(root: HTMLElement, model: ShellModel, actions: ShellActions): void {
42	  const view = element('div', { class: 'shell' });
43	  view.append(text('h1', 'CipherBox'));
44	
45	  if (model.phase === 'starting') view.append(note('Starting…'));
46	  else if (model.phase === 'signedIn') view.append(signedIn(model, actions));
47	  else view.append(frontDoor(model, actions));
48	
49	  if (model.error !== null) {
50	    view.append(text('p', model.error, { class: 'error', role: 'alert' }));
51	  }
52	  root.replaceChildren(view);
53	}
