55	function frontDoor(model: ShellModel, actions: ShellActions): HTMLElement {
56	  const section = element('section', { class: 'front-door' });
57	  section.append(note('Sign in to connect this device to your vault.'));
58	
59	  const offered = model.methods.flatMap((method) => {
60	    const render = RENDERERS[method];
61	    return render ? [render(model, actions)] : [];
62	  });
63	  if (offered.length === 0) {
